package com.oreummok.nativeapp;
import android.content.Context;import android.graphics.*;import android.view.*;import org.json.*;import java.util.*;
public class StairCanvas extends View {
 public JSONObject model;float yaw=-.6f,pitch=.55f;float lastX,lastY;Paint paint=new Paint(3);public StairCanvas(Context c){super(c);setBackgroundColor(Color.rgb(238,242,233));}
 double[] project(double x,double y,double z){double rx=x*Math.cos(yaw)-y*Math.sin(yaw),ry=x*Math.sin(yaw)+y*Math.cos(yaw);return new double[]{rx,ry*Math.sin(pitch)-z*Math.cos(pitch),ry*Math.cos(pitch)+z*Math.sin(pitch)};}
 static class Face{double[][] v;double depth;int color;Face(double[][]v,double depth,int color){this.v=v;this.depth=depth;this.color=color;}}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);paint.setColor(Color.rgb(28,58,45));paint.setTextSize(28);if(model==null){canvas.drawText("치수 입력 후 계산을 눌러 주세요.",20,42,paint);return;}try{ArrayList<Face>faces=new ArrayList<>();double minX=1e20,maxX=-1e20,minY=1e20,maxY=-1e20;JSONArray boxes=model.getJSONArray("boxes");int[][] indices={{0,1,2,3},{4,5,6,7},{0,1,5,4},{1,2,6,5},{2,3,7,6},{3,0,4,7}};int[]colors={0xff704f32,0xffc9a16b,0xffa17043,0xff8c5e37,0xff96683e,0xffae7e4c};for(int n=0;n<boxes.length();n++){JSONObject b=boxes.getJSONObject(n);double x=b.getDouble("x"),y=b.getDouble("y"),z=b.getDouble("z"),w=b.getDouble("width"),d=b.getDouble("depth"),t=b.getDouble("thickness");double[][]v={{x,y,z},{x+w,y,z},{x+w,y+d,z},{x,y+d,z},{x,y,z+t},{x+w,y,z+t},{x+w,y+d,z+t},{x,y+d,z+t}},p=new double[8][];for(int i=0;i<8;i++){p[i]=project(v[i][0],v[i][1],v[i][2]);minX=Math.min(minX,p[i][0]);maxX=Math.max(maxX,p[i][0]);minY=Math.min(minY,p[i][1]);maxY=Math.max(maxY,p[i][1]);}for(int f=0;f<6;f++){double[][] points=new double[4][];double dep=0;for(int j=0;j<4;j++){points[j]=p[indices[f][j]];dep+=points[j][2]/4;}faces.add(new Face(points,dep,colors[f]));}}double scale=Math.min((getWidth()-70)/Math.max(1,maxX-minX),(getHeight()-85)/Math.max(1,maxY-minY)),cx=(minX+maxX)/2,cy=(minY+maxY)/2;Collections.sort(faces,(a,b)->Double.compare(a.depth,b.depth));for(Face f:faces){Path path=new Path();for(int j=0;j<4;j++){float x=(float)(getWidth()/2+(f.v[j][0]-cx)*scale),y=(float)(getHeight()/2+(f.v[j][1]-cy)*scale);if(j==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();paint.setStyle(Paint.Style.FILL);paint.setColor(f.color);canvas.drawPath(path,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1);paint.setColor(0xff65482d);canvas.drawPath(path,paint);}paint.setStyle(Paint.Style.FILL);paint.setColor(0xff203a2f);paint.setTextSize(24);canvas.drawText("3D 치수 모형 · 드래그 회전 · 시공 승인 아님",15,30,paint);}catch(Exception e){canvas.drawText("모형 표시 실패",20,42,paint);}}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){yaw+=(e.getX()-lastX)*.008;pitch=Math.max(.03f,Math.min(1.53f,pitch-(e.getY()-lastY)*.006f));lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
}
